<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
const props=withDefaults(defineProps<{entries?:any[];maxLines?:number;autoScroll?:boolean;wrap?:boolean;level?:string;deviceKey?:string;locale?:string}>(),{entries:()=>[],maxLines:100,autoScroll:true,wrap:true})
const list=ref<HTMLElement>()
const entries=computed(()=>props.entries.filter(entry=>entry&&typeof entry==='object'&&(!props.level||props.level==='all'||entry.level===props.level)&&(!props.deviceKey||entry.deviceKey===props.deviceKey)).slice(-Math.max(1,Math.min(10000,Number(props.maxLines)||100))))
watch(entries,async()=>{if(props.autoScroll){await nextTick();if(list.value)list.value.scrollTop=list.value.scrollHeight}},{deep:true})
function timestamp(value:any){if(value===undefined||value===null)return '';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleTimeString(props.locale)}
</script>
<template><div ref="list" class="structured-log" :class="{wrap}" role="log" aria-live="off"><div v-for="(entry,index) in entries" :key="entry.id??index" class="structured-log-entry" :data-level="entry.level??'info'"><time>{{timestamp(entry.timestamp)}}</time><span v-if="entry.deviceKey" class="log-device">{{entry.deviceKey}}</span><strong>{{entry.level??entry.kind??'info'}}</strong><span>{{entry.message??(typeof entry.data==='string'?entry.data:JSON.stringify(entry.data??entry))}}</span></div><small v-if="!entries.length">{{locale?.startsWith('en')?'No log entries':'暂无日志'}}</small></div></template>
<style scoped>.structured-log{overflow:auto;min-height:0;flex:1;font:11px/1.6 Consolas,monospace;background:#f6f8fa;color:#324053;padding:6px}.structured-log-entry{display:flex;gap:8px;white-space:pre;align-items:baseline}.structured-log.wrap .structured-log-entry{white-space:pre-wrap;overflow-wrap:anywhere}.structured-log-entry time,.structured-log-entry strong,.log-device{flex-shrink:0}.structured-log-entry strong{font-weight:500;color:#68768a}.structured-log-entry[data-level=error],.structured-log-entry[data-level=error] strong{color:#b10e1e}.structured-log-entry[data-level=warning],.structured-log-entry[data-level=warn]{color:#8a5a00}</style>
